const companies=['Colafix','Fixcol','Argamazza'],suppliers=['Votorantim','Intercement'],carriers=['Itamar','Marielo'],statuses=['Agendado','Carregado','Entregue','Cancelado'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),opts=(values,selected='')=>values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join(''),day=s=>s.split('-').reverse().join('/');let loads=[];
const statusClass=s=>({Agendado:'scheduled',Carregado:'loaded',Entregue:'delivered',Cancelado:'cancelled'}[s]||'scheduled');
const labels={scheduledDate:'Data agendada',company:'Empresa',supplier:'Fornecedor',carrier:'Transportador',systemOrder:'Pedido do sistema',supplierOrder:'Pedido do fornecedor',invoice:'Número da NF',status:'Status',notes:'Observações',kind:'Tipo'};
async function refresh(){const response=await fetch('/api/cement');if(!response.ok)throw Error('Não foi possível carregar as cargas.');loads=(await response.json()).loads;for(const kind of ['granel','ensacado'])renderList(kind);}
async function save(row){const response=await fetch('/api/cement',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(row)}),result=await response.json();if(!response.ok)throw Error(result.error);await refresh();return result.load;}
for(const kind of ['granel','ensacado']){const root=document.querySelector('#'+kind+'-view');root.innerHTML=`<section class="panel cement-form-panel"><h3>Agendar carga</h3><form data-kind="${kind}"><div class="cement-fields"><label>Data agendada<input name="scheduledDate" type="date" required></label><label>Empresa<select name="company">${opts(companies)}</select></label><label>Fornecedor<select name="supplier">${opts(suppliers)}</select></label><label>Transportador<select name="carrier">${opts(carriers)}</select></label><label>Pedido do sistema<input name="systemOrder" maxlength="120" required></label><label>Pedido do fornecedor<input name="supplierOrder" maxlength="120"></label><label>Número da NF<input name="invoice" maxlength="120"></label><label>Status<select name="status" class="load-status scheduled">${opts(statuses)}</select></label><label class="cement-notes">Observações<textarea name="notes" maxlength="2000" rows="2"></textarea></label></div><button type="submit">Salvar agendamento</button> <button type="button" data-cancel hidden>Cancelar edição</button><p class="cement-message" role="status"></p></form></section><section class="panel cement-list-panel"><h3>Acompanhamento de cargas</h3><div class="cement-filters"><label>Empresa<select data-company><option value="">Todas</option>${opts(companies)}</select></label><label>Status<select data-status><option value="">Todos</option>${opts(statuses)}</select></label><label>Buscar pedido, NF ou transportador<input type="search" data-search></label></div><div class="cement-list"></div></section>`;
const form=root.querySelector('form'),message=root.querySelector('.cement-message');form.elements.status.disabled=true;form.elements.status.onchange=()=>form.elements.status.className='load-status '+statusClass(form.elements.status.value);root.querySelectorAll('[data-company],[data-status],[data-search]').forEach(el=>el.addEventListener('input',()=>renderList(kind)));
function reset(){form.reset();form.elements.status.disabled=true;form.elements.status.className='load-status scheduled';delete form.dataset.id;delete form.dataset.version;root.querySelector('[data-cancel]').hidden=true;root.querySelector('.cement-form-panel h3').textContent='Agendar carga';}
root.querySelector('[data-cancel]').onclick=()=>{reset();message.textContent='Edição cancelada.';};
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;message.textContent='Salvando…';try{const input={...Object.fromEntries(new FormData(form)),kind,status:form.elements.status.value};if(form.dataset.id){input.id=form.dataset.id;input.version=Number(form.dataset.version);}await save(input);reset();message.textContent='Carga salva. Você pode atualizar o status na lista abaixo.';}catch(e){message.textContent=e.message;}finally{button.disabled=false;}};
}
function renderList(kind){const root=document.querySelector('#'+kind+'-view'),q=root.querySelector('[data-search]').value.toLocaleLowerCase('pt-BR'),company=root.querySelector('[data-company]').value,status=root.querySelector('[data-status]').value;const rows=loads.filter(r=>r.kind===kind&&(!company||r.company===company)&&(!status||r.status===status)&&[r.systemOrder,r.supplierOrder,r.invoice,r.carrier].join(' ').toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>b.scheduledDate.localeCompare(a.scheduledDate)||b.createdAt.localeCompare(a.createdAt));
root.querySelector('.cement-list').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr>${['Data','Empresa','Pedido sistema','Fornecedor','Pedido fornecedor','Transportador','NF','Status','Ações'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${day(r.scheduledDate)}</td><td>${esc(r.company)}</td><td>${esc(r.systemOrder)}</td><td>${esc(r.supplier)}</td><td>${esc(r.supplierOrder||'—')}</td><td>${esc(r.carrier)}</td><td>${esc(r.invoice||'—')}</td><td><select class="load-status ${statusClass(r.status)}" data-load-status="${r.id}" aria-label="Status do pedido ${esc(r.systemOrder)}">${opts(statuses,r.status)}</select></td><td><button data-edit="${r.id}">Editar</button><details><summary>Histórico</summary><ol class="load-timeline">${r.history.filter(h=>h.changes?.status).map(h=>`<li><span class="load-status ${statusClass(h.changes.status.after)}">${esc(h.changes.status.after)}</span><time datetime="${esc(h.at)}">${esc(new Date(h.at).toLocaleString('pt-BR'))}</time></li>`).join('')}</ol></details></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-state">Nenhuma carga encontrada. Cadastre o primeiro agendamento acima.</p>';
root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=loads.find(r=>r.id===b.dataset.edit),form=root.querySelector('form');for(const [k,v] of Object.entries(r))if(form.elements.namedItem(k))form.elements.namedItem(k).value=v;form.dataset.id=r.id;form.dataset.version=r.version;form.elements.status.disabled=false;form.elements.status.className='load-status '+statusClass(r.status);root.querySelector('[data-cancel]').hidden=false;root.querySelector('.cement-form-panel h3').textContent='Editar carga · pedido '+r.systemOrder;root.querySelector('.cement-message').textContent='';form.scrollIntoView({behavior:'smooth'});});
root.querySelectorAll('[data-load-status]').forEach(select=>select.onchange=async()=>{const r=loads.find(r=>r.id===select.dataset.loadStatus),message=root.querySelector('.cement-message');select.disabled=true;try{await save({...r,status:select.value});message.textContent='Status atualizado e registrado no histórico.';}catch(e){select.value=r.status;select.disabled=false;message.textContent=e.message;}});
}
refresh().catch(e=>document.querySelectorAll('.cement-message').forEach(p=>p.textContent=e.message));
